import { match, P } from './index';

describe('symbol and non-enumerable object pattern keys', () => {
  it('discovers selections through symbol and non-enumerable keys', () => {
    const symbolKey = Symbol('symbol-key');
    const hiddenKey = 'hidden-key';
    const nestedPattern: Record<PropertyKey, unknown> = {};

    Object.defineProperty(nestedPattern, symbolKey, {
      value: P.select('symbolSelection'),
      enumerable: false,
    });
    Object.defineProperty(nestedPattern, hiddenKey, {
      value: P.select('hiddenSelection'),
      enumerable: false,
    });

    const pattern = {
      outer: P.optional(nestedPattern),
    };

    expect(
      match({})
        .with(pattern as any, (selection) => selection)
        .otherwise(() => 'unmatched')
    ).toEqual({
      symbolSelection: undefined,
      hiddenSelection: undefined,
    });
  });

  it('initializes selections through symbol and non-enumerable keys for empty arrays', () => {
    const symbolKey = Symbol('symbol-key');
    const hiddenKey = 'hidden-key';
    const nestedPattern: Record<PropertyKey, unknown> = {};

    Object.defineProperty(nestedPattern, symbolKey, {
      value: P.select('symbolSelection'),
      enumerable: false,
    });
    Object.defineProperty(nestedPattern, hiddenKey, {
      value: P.select('hiddenSelection'),
      enumerable: false,
    });

    expect(
      match({ values: [] })
        .with({ values: P.array(nestedPattern as any) } as any, (selection) =>
          selection
        )
        .otherwise(() => 'unmatched')
    ).toEqual({
      symbolSelection: [],
      hiddenSelection: [],
    });
  });

  it('ignores inherited pattern keys but matches inherited value properties', () => {
    const inheritedPattern = Object.assign(
      Object.create({ ignored: 'not required' }),
      { own: 'value' }
    );
    const inheritedValue = Object.create({ own: 'value' });

    expect(
      match(inheritedValue)
        .with(inheritedPattern, () => true)
        .otherwise(() => false)
    ).toBe(true);
  });
});
