describe('object pattern own keys', () => {
  it('discovers selections under symbol and non-enumerable keys in absent optional patterns', () => {
    const symbolKey = Symbol('symbol key');
    const pattern = {} as Record<PropertyKey, unknown>;

    Object.defineProperty(pattern, symbolKey, {
      value: P.select('symbolSelection'),
      enumerable: false,
    });
    Object.defineProperty(pattern, 'hidden', {
      value: P.select('hiddenSelection'),
      enumerable: false,
    });

    const result = match({})
      .with({ nested: P.optional(pattern as any) } as any, (selection) =>
        selection
      )
      .otherwise(() => 'did not match');

    expect(result).toEqual({
      symbolSelection: undefined,
      hiddenSelection: undefined,
    });
  });

  it('discovers selections under symbol and non-enumerable keys in empty arrays', () => {
    const symbolKey = Symbol('symbol key');
    const pattern = {} as Record<PropertyKey, unknown>;

    Object.defineProperty(pattern, symbolKey, {
      value: P.select('symbolSelection'),
      enumerable: false,
    });
    Object.defineProperty(pattern, 'hidden', {
      value: P.select('hiddenSelection'),
      enumerable: false,
    });

    const result = match({ nested: [] })
      .with({ nested: P.array(pattern as any) } as any, (selection) =>
        selection
      )
      .otherwise(() => 'did not match');

    expect(result).toEqual({
      symbolSelection: [],
      hiddenSelection: [],
    });
  });

  it('matches own symbol and non-enumerable pattern keys', () => {
    const symbolKey = Symbol('symbol key');
    const pattern = {} as Record<PropertyKey, unknown>;
    const value = {} as Record<PropertyKey, unknown>;

    Object.defineProperty(pattern, symbolKey, {
      value: P.select('symbolSelection'),
      enumerable: false,
    });
    Object.defineProperty(pattern, 'hidden', {
      value: P.select('hiddenSelection'),
      enumerable: false,
    });
    Object.defineProperty(value, symbolKey, { value: 1, enumerable: false });
    Object.defineProperty(value, 'hidden', { value: 2, enumerable: false });

    const result = match(value)
      .with(pattern as any, (selection) => selection)
      .otherwise(() => 'did not match');

    expect(result).toEqual({ symbolSelection: 1, hiddenSelection: 2 });
  });

  it('ignores inherited pattern keys while matching inherited value properties', () => {
    const inheritedPattern = { inherited: P.select('inheritedSelection') };
